"""Opt-in, offline dedicated QLoRA training; default is a light preflight."""
from __future__ import annotations

import argparse
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
if (ROOT / "src" / "fanyiji" / "specialized_training.py").is_file():
    sys.path.insert(0, str(ROOT / "src"))
    from fanyiji.specialized_training import (
        TrainingExecutionError, TrainingPreparationError, preflight, train_local_adapter,
    )
else:
    # A preparation generated by the packaged desktop app carries an adjacent
    # standalone module; it does not depend on the app package being installed.
    from specialized_training import (
        TrainingExecutionError, TrainingPreparationError, preflight, train_local_adapter,
    )


def main(argv=None) -> int:
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8")
    parser = argparse.ArgumentParser(description="专用本地翻译模型训练；使用始终锁定")
    parser.add_argument("--root", type=Path, required=True, help="专用模型数据目录")
    parser.add_argument("--dataset", type=Path, help="经过审核的版本化数据导出目录")
    parser.add_argument("--base-model", type=Path, help="本地 Hy-MT2-1.8B HF safetensors 目录")
    action = parser.add_mutually_exclusive_group()
    action.add_argument("--preflight", action="store_true", help="只检查资料，不加载模型（默认）")
    action.add_argument("--train", action="store_true", help="在独立环境显式执行 QLoRA")
    args = parser.parse_args(argv)
    if args.train and args.dataset is None:
        parser.error("--train 必须指定 --dataset")
    try:
        if args.train:
            result = train_local_adapter(args.root, dataset=args.dataset, base_model=args.base_model)
        else:
            result = preflight(args.root, dataset=args.dataset, base_model=args.base_model)
        print(json.dumps(result, ensure_ascii=False, indent=2, allow_nan=False))
        return 0 if result.get("status") == "completed_locked" or result.get("assets_ready") else 2
    except (OSError, TrainingPreparationError) as exc:
        print(json.dumps({"status": "blocked", "deployment_locked": True,
                          "training_executed": False, "reason": str(exc)}, ensure_ascii=False))
        return 2
    except TrainingExecutionError as exc:
        print(json.dumps({"status": "failed", "deployment_locked": True,
                          "training_executed": True,
                          "reason": "请检查专用训练目录的 failure.json",
                          "error_type": type(exc).__name__}, ensure_ascii=False))
        return 1
    except Exception as exc:
        print(json.dumps({"status": "failed", "deployment_locked": True,
                          "training_executed": False,
                          "reason": "训练环境初始化失败，未开始模型训练",
                          "error_type": type(exc).__name__}, ensure_ascii=False))
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
